function skillCostLabel(build){let blood=hasKey('blood');if(GEM[build.type]?.signature===52){let extra=Math.min(30,Math.max(0,p.mp-(blood?0:build.cost)));return blood?Math.ceil(build.cost)+' LIFE +'+Math.ceil(extra)+' MANA':Math.ceil(build.cost+extra)+' MANA';}return Math.ceil(build.cost)+(blood?' LIFE':' MANA');}
// Six equipped-gem skill slots, separate from the basic attack and dodge.
function skillPadLabel(i){let base=i<2?['skill1','skill2'][i]:['skill1','skill2','accept','back'][i-2];let prefix=i<2?'':(padProfile.buttons.secondary===6?'ZL':'Btn '+padProfile.buttons.secondary)+' + ';return prefix+tutorialButton(base)}
function skillSlotPress(i){if(!skillBuild(p.bindings[i])){panel('gems');document.querySelectorAll('.bindings select')[i]?.focus();return}cast(SKILL_ACTIONS[i])}
for(let i=2;i<6;i++)document.querySelector('.actions').insertAdjacentHTML('beforeend','<button class="extra-skill" data-slot="'+i+'" onclick="skillSlotPress('+i+')">'+iconMarkup('spell','bar-icon')+'<kbd>'+SKILL_KEYS[i]+'</kbd><strong>未割当</strong><small></small></button>');
const multiSlotHud=drawHud;drawHud=()=>{multiSlotHud();if(!p)return;let buttons=document.querySelectorAll('.actions button'),shift=padActive&&padDevice&&padDown(padDevice,'secondary');for(let i=0;i<6;i++){let button=i<2?buttons[i+1]:buttons[i+3];if(!button)continue;let type=p.bindings[i],build=skillBuild(type),action=SKILL_ACTIONS[i],idx=ICONS[type]??8;hudText(button.querySelector('kbd'),padActive&&padDevice?skillPadLabel(i):SKILL_KEYS[i]);hudText(button.querySelector('strong'),build?gemDisplayName(build.gem):type?'未装着':'未割当');hudText(button.querySelector('small'),build?(cd[action]>.05?cd[action].toFixed(1)+' s':skillCostLabel(build)):'Gで設定');button.querySelector('.bar-icon').style.backgroundPosition=(idx%4)*100/3+'% '+Math.floor(idx/4)*50+'%';button.style.setProperty('--cool',build?Math.min(1,cd[action]/build.cool):0);button.classList.toggle('skill-empty',!build);button.classList.toggle('shift-ready',!!shift&&i>=2);hudTitle(button,'枠 '+(i+1)+' · '+SKILL_KEYS[i]+' / '+skillPadLabel(i)+' · '+(build?gemDisplayName(build.gem):'ジェムを装着して割り当て'));}if(padActive&&padDevice)hudText(document.querySelector('.hint'),'Y / X スキル1–2 · ZL + Y / X / A / B スキル3–6 · ZR 攻撃 · B 回避 · A 調べる');else hudText(document.querySelector('.hint'),'Q E R T Y U：6つのスキル · SPACE 回避 · 1 生命瓶 · G ジェム設定')};
const multiSlotUpdate=update;update=dt=>{multiSlotUpdate(dt);if(!started||paused||dead||playerAction)return;for(let i=2;i<6;i++)if(keys[SKILL_KEYS[i].toLowerCase()]){cast(SKILL_ACTIONS[i]);if(playerAction)break}};
addEventListener('keydown',e=>{if(!started||paused||dead||e.repeat||e.ctrlKey||e.metaKey||e.altKey)return;let i=SKILL_KEYS.indexOf(e.key.toUpperCase());if(i>=2){e.preventDefault();cast(SKILL_ACTIONS[i])}});
const multiSlotPanel=panel;panel=kind=>{multiSlotPanel(kind);if(kind==='gems'&&!tutorialGuideOpen){let bindings=$('card').querySelector('.bindings');bindings?.insertAdjacentHTML('beforebegin','<p id="skillSlotsGuide" class="skill-slots-guide">6つのスキル枠：Y / X と ZL＋Y / X / A / B。装着済みのアクティブジェムを割り当てます。サポートはリンク先に自動適用。</p>');$('card').querySelectorAll('.bindings label').forEach((label,i)=>{label.insertAdjacentHTML('afterbegin','<span class="skill-pad-label">枠 '+(i+1)+' · '+skillPadLabel(i)+'</span>')})}};

